ight\":1,\"ctaBtnLinkColor\":\"var(\\u002d\\u002dast-global-color-2)\",\"ctaLinkHoverColor\":\"var(\\u002d\\u002dast-global-color-5)\",\"ctaBgColor\":\"#ffffff00\",\"ctaBgHoverColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"ctaBorderColor\":\"\",\"ctaBorderStyle\":\"\",\"showIcon\":false,\"paddingBtnTop\":16,\"paddingBtnBottom\":16,\"paddingBtnLeft\":20,\"paddingBtnRight\":20,\"prefixTopMargin\":0,\"prefixRightMargin\":0,\"prefixSpace\":20,\"prefixLeftMargin\":0,\"prefixLetterSpacing\":2,\"headTopMargin\":0,\"headRightMargin\":0,\"headLeftMargin\":0,\"headMarginTopTablet\":0,\"headMarginRightTablet\":0,\"headTabletSpace\":0,\"headMarginLeftTablet\":0,\"headMarginTopMobile\":0,\"headMarginRightMobile\":0,\"headMobileSpace\":0,\"headMarginLeftMobile\":0,\"blockTopPadding\":0,\"blockRightPadding\":0,\"blockLeftPadding\":0,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":0,\"blockLeftPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockPaddingLink\":false,\"separatorMarginTopTablet\":0,\"separatorMarginRightTablet\":0,\"seperatorTabletSpace\":10,\"separatorMarginLeftTablet\":0,\"separatorMarginTopMobile\":0,\"separatorMarginRightMobile\":0,\"seperatorMobileSpace\":10,\"separatorMarginLeftMobile\":0,\"subHeadTopMargin\":0,\"subHeadRightMargin\":0,\"subHeadLeftMargin\":0,\"subHeadMarginTopTablet\":20,\"subHeadMarginRightTablet\":0,\"subHeadTabletSpace\":0,\"subHeadMarginLeftTablet\":0,\"subHeadMarginTopMobile\":20,\"subHeadMarginRightMobile\":0,\"subHeadMobileSpace\":0,\"subHeadMarginLeftMobile\":0,\"btnBorderTopWidth\":1,\"btnBorderLeftWidth\":1,\"btnBorderRightWidth\":1,\"btnBorderBottomWidth\":1,\"btnBorderTopLeftRadius\":6,\"btnBorderTopRightRadius\":6,\"btnBorderBottomLeftRadius\":6,\"btnBorderBottomRightRadius\":6,\"btnBorderStyle\":\"solid\",\"btnBorderColor\":\"#333\",\"btnBorderHColor\":\"var(\\u002d\\u002das