et\":18,\"headFontSizeMobile\":16,\"subHeadTransform\":\"\",\"blockTopPadding\":0,\"blockRightPadding\":0,\"blockLeftPadding\":0,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":0,\"blockLeftPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockTopMargin\":0,\"blockRightMargin\":0,\"blockLeftMargin\":0,\"blockBottomMargin\":0,\"blockTopMarginTablet\":0,\"blockRightMarginTablet\":0,\"blockLeftMarginTablet\":0,\"blockBottomMarginTablet\":0,\"blockTopMarginMobile\":0,\"blockRightMarginMobile\":0,\"blockLeftMarginMobile\":0,\"blockBottomMarginMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-bcf170a6\"><div class=\"uagb-heading-text\">Email</div><p class=\"uagb-desc-text\">forthouser@gmail.com</p></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://forthouse-reserve.com/profile\">Download Our Company Profile</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/separator {\"block_id\":\"e6f07a50\",\"separatorBorderHeight\":1,\"separatorBorderHeightMobile\":1,\"separatorBorderHeightTablet\":1,\"separatorColor\":\"var(\\u002d\\u002dast-global-color-6)\",\"separatorHeight\":0,\"separatorHeightMobile\":0,\"separatorHeightTablet\":0,\"blockTopPadding\":20,\"blockBottomPadding\":20,\"blockTopPaddingTablet\":15,\"blockBottomPaddingTablet\":15,\"blockTopPaddingMobile\":15,\"blockBottomPaddingMobile\":15,\"blockPaddingUnit\":\"px\",\"blockPaddingUnitTablet\":\"px\",\"blockPaddingUnitMobile\":\"px\"} -->\n<div class=\"wp-block-uagb-separator uagb-block-e6f07a50\"><div class=\"uagb-separator-spacing-wrapper\"><div class=\"wp-block-uagb-separator__inner\" style=\"--my-background-image:\"></div>