INSERT INTO `wp_wfissues` VALUES (262,1738308021,1738308021,'new','skippedPaths',25,'6fd0d290b978eab8027e6b79501ac149','6fd0d290b978eab8027e6b79501ac149','1 path was skipped for the malware scan due to scan settings','The option \"Scan files outside your WordPress installation\" is off by default, which means 1 path and its file(s) will not be scanned for malware or unauthorized changes. To continue skipping this path, you may ignore this issue. Or to start scanning it, enable the option and subsequent scans will include it. Some paths may not be necessary to scan, so this is optional. <a href=\"https://www.wordfence.com/help/?query=scan-result-skipped-paths\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More<span class=\"screen-reader-text\"> (opens in new tab)</span></a><br><br>The path skipped is /mnt/volume_lon1_01/html/fort/.git','a:0:{}'),(271,1738308304,1738308304,'new','suspiciousAdminUsers',75,'3457e1a41965cec8fc2457d2d142c5fb','3457e1a41965cec8fc2457d2d142c5fb','An admin user with the username forthous54 was created outside of WordPress.','An admin user with the username forthous54 was created outside of WordPress. It\'s possible a plugin could have created the account, but if you do not recognize the user, we suggest you remove it.','a:1:{s:6:\"userID\";i:11;}'),(280,1738438376,1738438376,'new','wfPluginUpgrade',50,'d346e08f6efdee52d047db88ca3199b3','d346e08f6efdee52d047db88ca3199b3','The Plugin \"Site Kit by Google\" needs an upgrade (1.142.0 -> 1.145.0).','You need to upgrade \"Site Kit by Google\" to the newest version to ensure you have any security fixes the developer has released.','a:22:{s:18:\"Requires Yoast SEO\";s:0:\"\";s:4:\"Name\";s:18:\"Site Kit by Google\";s:9:\"PluginURI\";s:30:\"https://sitekit.withgoogle.com\";s:7:\"Version\";s:7:\"1.142.0\";s:11:\"Description\";s:125:\"Site Kit is a one-stop solution for WordPress users to use everything Google has to offer to make them successful on the web.\";s:6:\"Author\";s:6:\"Google\";s:9:\